#!/usr/bin/env python3
"""Private JOY VIMO QA: privacy/release static gate, not proof of device behavior."""
from pathlib import Path
import json, sys
root=Path(__file__).resolve().parents[1]
app=(root/"App.js").read_text()
module=(root/"modules/joy-vimo-usage/android/src/main/java/com/joyvimo/usage/JoyVimoUsageModule.kt").read_text()
service=(root/"modules/joy-vimo-usage/android/src/main/java/com/joyvimo/usage/JoyVimoFocusService.kt").read_text()
manifest=(root/"modules/joy-vimo-usage/android/src/main/AndroidManifest.xml").read_text()
config=(root/"modules/joy-vimo-usage/android/src/main/res/xml/joy_vimo_accessibility_config.xml").read_text()
workflow=(root/".github/workflows/android-qa-apk.yml").read_text()
package=json.loads((root/"package.json").read_text())
app_cfg=json.loads((root/"app.json").read_text())
errors=[]
def must(check,why):
    if not check:errors.append(why)
must("clearFocusConfig" in module and "eraseDeviceData" in app and "clearFocusConfig" in (root/"lib/localErase.js").read_text(),"Native focus settings must be wiped on data deletion")
must("consented" in module and "consented" in service,"Native enforcement requires recorded opt-in")
must('age!="kid"' in module and 'getString("age","kid")!="kid"' in service,"Parent-supported mode must fail closed")
must('android:canRetrieveWindowContent="true"' in config and 'android:accessibilityFlags="flagReportViewIds"' in config,"YouTube screen resource-ID capability must be declared")
must("youtubeShorts" in (root/"components/FocusControl.js").read_text() or "setShorts" in (root/"components/FocusControl.js").read_text(),"Separate YouTube Shorts opt-in must exist")
must("checkChromeDomain" in service and "domain_rules_enabled" in service,"Website rules must remain opt-in")
must("findAccessibilityNodeInfosByViewId" in service and "com.android.chrome:id/url_bar" in service,"Limit domain inspection to Chrome URL bar")
must("getText()" not in service and "Log." not in service,"Do not log or broadly read Accessibility node content")
must("domainRulesEnabled" in (root/"components/DomainRulesPanel.js").read_text() or "onEnabledChange" in (root/"components/DomainRulesPanel.js").read_text(),"Website rule control must exist")
must("FeedInterruptionControls" in app,"Instagram/TikTok opt-in UI must be present in app")
must("instagramReels" in (root/"components/FeedInterruptionControls.js").read_text() and "tiktokFeed" in (root/"components/FeedInterruptionControls.js").read_text(),"Independent feed controls required")
must("instagram_reels" in service and "tiktok_feed" in service,"Native feed feature flags required")
must("getBoundsInScreen" in service,"Experimental feed detection must validate fullscreen geometry")
pause=(root/"modules/joy-vimo-usage/android/src/main/java/com/joyvimo/usage/JoyVimoOpeningPauseActivity.kt").read_text()
must("JoyVimoOpeningPauseActivity" in manifest and 'android:exported="false"' in manifest,"Pause Activity must not be exported")
must("safety_pause_until" in service and "pauseFocusSafely" in module,"Emergency pause must be available")
must("opening_bypass_until_" in service and "opening_bypass_until_" in pause,"Opening pause must guard against reopen loops")
# Three-denial cooldown must be scoped per app and per day, and cannot trap users.
must('denied_day_'+ '"' in service and 'denied_attempts_' in service and 'denied_cooldown_' in service,"Native three-denial counters and cooldown must exist")
must('nextDenied>=denialLimit' in service and 'cooldownMinutes' in service and 'coerceIn(5,30)' in service,"Configured denied attempts must start a bounded cooldown")
must('cooldownEnabled' in service and 'denialLimit' in module and 'cooldownMinutes' in module,"Optional per-app cooldown must be validated by native code")
opening=service.split('private fun recordOpening(pkg:String,now:Long)',1)[-1].split('private fun isActive()',1)[0]
must('if(!protectionRunning())return' in opening and 'val safetyUntil=prefs.getLong("safety_pause_until",0L)' in opening and 'if(now<safetyUntil)return' in opening,"Emergency pause, disabled consent and locked device must bypass attempt counting")
must('private fun protectionRunning():Boolean' in service and 'isActive() && isDeviceAccessible()' in service and 'System.currentTimeMillis()>=prefs.getLong("safety_pause_until",0L)' in service,"Central protection guard must verify consent, interactive unlock state and safety pause")
must('three_attempt_cooldown' in service and 'redirect(name,pkg' in service,"Cooldown must use existing redirect path")
must("delay" in service and 'put("delay"' in module,"Per-app opening delay must reach native service")
must("Go Home" in pause and "Safety pause" in pause,"Pause screen must offer safe exit and temporary bypass")
must("protectionRunning()" in service and service.count("protectionRunning()")>=5,"All feed/website interventions must respect safety pause")
must("scheduleActive" in (root/"lib/scheduleRules.js").read_text(),"Schedule boundary helper must exist")
must("inPresetSchedule" in service and "selected(yesterday)" in service,"Overnight weekday schedules must be handled")
must("startStrictMode" in module and 'remove("strict_until")' in module,"Strict window must be voluntary and cleared on disable")
must("pauseFocusSafely" in module and "clearFocusConfig" in module,"Emergency bypass and revoke must remain available")
must("ScheduleEditor" in app,"Editable schedule screen must be wired in")
must("service_heartbeat_at" in service and "serviceHealthy" in module,"Service heartbeat health checks required")
must("if(!protectionRunning())return" in service and "lastEntryByPackage[pkg]" in service,"App opening counts must respect lock/safety state and per-app duplicate events")
must("lastEntryMs" not in service,"Global opening debounce must not suppress separate app launches")
must("elapsedRealtime" in service and "activeSessionMs" in service,"Session timing must use monotonic active time")
must("openBatteryOptimizationSettings" in module,"User-facing battery settings access required")
must("android.permission.BIND_ACCESSIBILITY_SERVICE" in manifest,"Accessibility must use system-protected binding permission")
must("Accessibility" in (root/"components/FocusControl.js").read_text(),"Consent UI must explain Accessibility")
must("workflow_dispatch:" in workflow and "\n  push:" not in workflow,"APK workflow must stay manual-only")
must("if: ${{ inputs.publish_private_apk }}" in workflow,"Owner APK artifact must be gated by explicit publish input")
must('JOY_QA_STORE_PASSWORD: ${{ secrets.JOY_QA_STORE_PASSWORD }}' in workflow and 'JOY_QA_KEY_ALIAS: ${{ secrets.JOY_QA_KEY_ALIAS }}' in workflow,"Stable signing variables must be passed to build and certificate verification")
build_step=workflow.split('      - name: Build bundled QA APK',1)[-1].split('      - name: Confirm APK generated',1)[0]
verify_step=workflow.split('      - name: Verify private APK signature and record fingerprint',1)[-1].split('      - name: Upload QA APK',1)[0]
must('JOY_QA_KEY_PASSWORD:' in build_step and 'JOY_QA_STORE_PASSWORD:' in build_step and 'JOY_QA_KEY_ALIAS:' in build_step,"Gradle build must receive the protected signing secrets")
must('JOY_QA_STORE_PASSWORD:' in verify_step and 'JOY_QA_KEY_ALIAS:' in verify_step,"APK certificate verification must receive the protected keystore credentials")
signing=(root/"scripts/ensure_qa_signing.py").read_text()
must("Stable signing secrets missing" in signing and "JOY_QA_KEYSTORE_BASE64" in signing,"Private APK must fail closed without reusable signing secrets")
must(app_cfg["expo"]["android"]["package"]=="com.joyvimo.app","QA package ID unexpectedly changed")
must("OfflineActivities" in app and "computeProgress" in app,"Offline activity and local progress flows required")
must("JoyCompanion" in app and "PrivacyDataPanel" in app and "DailyReminders" in app,"New user-facing features must be wired into App.js")
must('accessibilityRole="tab"' in app and 'accessibilityState={{selected:tab===n}}' in app,"Bottom navigation must expose tab state")
must('minHeight:44,minWidth:44' in app and 'minHeight:mobile.tabHeight' in app and 'mobileLayout(screenWidth,fontScale)' in app,"Key navigation and choice targets must retain minimum accessible hit areas with responsive navigation")
layout=(root/"lib/mobileLayout.js").read_text()
must('tabHeight:scale>=1.5?80:enlarged?70:58' in layout and 'tabBarHeight:scale>=1.5?86:enlarged?76:66' in layout,"Responsive tab sizes must preserve at least 58dp touch height")
must("makeFocusPayload(data,status)" in app and "data.rules,data.schedules" in app,"One parent synchronization path must track rule and schedule changes")
must("Native rule/schedule synchronization is owned by AppMain" in (root/"components/FocusControl.js").read_text(),"FocusControl must not duplicate parent native synchronization")
must("expo-notifications" in package["dependencies"],"Local reminder dependency missing")
feed=(root/"components/OfflineActivities.js").read_text()
must("joy-feed-hidden-v1" in feed and "AsyncStorage.setItem" in feed and "AsyncStorage.removeItem" in feed,"Feed hidden preferences must persist and support restoring")
must("tests/progress.test.cjs" in workflow,"Progress regression checks required")
must("withPrivateAndroidSettings" in app_cfg["expo"].get("plugins",[])[0],"Android backup privacy plugin missing")
plugin=(root/"plugins/withPrivateAndroidSettings.js").read_text()
must("android:allowBackup" in plugin and "'false'" in plugin,"Android backup must be disabled")
leaderboard=(root/"components/AdultLeaderboard.js").read_text()
must("joy_weekly_leaderboard" in leaderboard and "p_country" in leaderboard,"Country/global leaderboard connection must be present")
must("joy_leave_leaderboard" in leaderboard and "joy_delete_leaderboard_data" in leaderboard,"Online opt-out and delete controls must remain present")
must("age==='adult'" in leaderboard,"Public online leaderboard must remain adult-only")
must("EXPO_PUBLIC_JOY_SUPABASE" in (root/"lib/joySupabase.js").read_text(),"Dedicated backend config required")
must("getSupportedAppsInstalled" in module and "getSupportedAppsInstalled" in app,"Supported app presence must be shown without broad query permission")
must("<queries>" in manifest and "QUERY_ALL_PACKAGES" not in manifest,"Declare only known packages for app visibility")
must("cancelSavedReminder" in app,"Local erase must also cancel daily reminders")
must("expo" in package["dependencies"],"Missing Expo dependency")
for hazard in ["READ_SMS","READ_CONTACTS","QUERY_ALL_PACKAGES","REQUEST_INSTALL_PACKAGES","READ_CALL_LOG"]:
    must(hazard not in manifest,"Unexpected sensitive permission in manifest: "+hazard)
if errors:
    for e in errors:print("FAIL:",e)
    sys.exit(1)
print("PASS: static privacy preflight (does NOT verify OS enforcement or APK security).")
